std::string BianHao_Trim(const std::string& value)
{
    size_t first = 0;
    while (first < value.size() && std::isspace(static_cast<unsigned char>(value[first])))
    {
        ++first;
    }

    size_t last = value.size();
    while (last > first && std::isspace(static_cast<unsigned char>(value[last - 1])))
    {
        --last;
    }

    return value.substr(first, last - first);
}

std::string BianHao_NormalizeText(const std::string& value)
{
    std::string text = BianHao_Trim(value);
    while (!text.empty() && (text.back() == '\r' || text.back() == '\n' || text.back() == '\t'))
    {
        text.pop_back();
        text = BianHao_Trim(text);
    }
    return text;
}

bool BianHao_IsValidUtf8(const std::string& value)
{
    int remaining = 0;
    for (size_t i = 0; i < value.size(); ++i)
    {
        const unsigned char ch = static_cast<unsigned char>(value[i]);
        if (remaining == 0)
        {
            if ((ch >> 7) == 0)
            {
                continue;
            }
            if ((ch >> 5) == 0x6)
            {
                remaining = 1;
            }
            else if ((ch >> 4) == 0xE)
            {
                remaining = 2;
            }
            else if ((ch >> 3) == 0x1E)
            {
                remaining = 3;
            }
            else
            {
                return false;
            }
        }
        else
        {
            if ((ch >> 6) != 0x2)
            {
                return false;
            }
            --remaining;
        }
    }
    return remaining == 0;
}

std::string BianHao_SystemToUtf8(const std::string& value)
{
    if (value.empty() || BianHao_IsValidUtf8(value))
    {
        return value;
    }

    int wideLength = MultiByteToWideChar(CP_ACP, 0, value.c_str(), -1, NULL, 0);
    if (wideLength <= 0)
    {
        return value;
    }

    std::wstring wide(static_cast<size_t>(wideLength), L'\0');
    if (MultiByteToWideChar(CP_ACP, 0, value.c_str(), -1, &wide[0], wideLength) <= 0)
    {
        return value;
    }

    int utf8Length = WideCharToMultiByte(CP_UTF8, 0, wide.c_str(), -1, NULL, 0, NULL, NULL);
    if (utf8Length <= 0)
    {
        return value;
    }

    std::string utf8(static_cast<size_t>(utf8Length), '\0');
    if (WideCharToMultiByte(CP_UTF8, 0, wide.c_str(), -1, &utf8[0], utf8Length, NULL, NULL) <= 0)
    {
        return value;
    }

    if (!utf8.empty() && utf8[utf8.size() - 1] == '\0')
    {
        utf8.pop_back();
    }
    return utf8;
}

std::string BianHao_NormalizeHeaderKey(const std::string& value)
{
    std::string text = BianHao_NormalizeText(value);
    std::string key;
    for (size_t i = 0; i < text.size(); ++i)
    {
        const unsigned char ch = static_cast<unsigned char>(text[i]);
        if (std::isspace(ch) || text[i] == ':' || text[i] == '[' || text[i] == ']' ||
            text[i] == '(' || text[i] == ')' || text[i] == '-' || text[i] == '_' ||
            text[i] == '.' || text[i] == '#')
        {
            continue;
        }

        if (ch < 0x80)
        {
            key.push_back(static_cast<char>(std::toupper(ch)));
        }
        else
        {
            key.push_back(text[i]);
        }
    }

    const std::string fullWidthSpace = "\xE3\x80\x80";
    size_t pos = std::string::npos;
    while ((pos = key.find(fullWidthSpace)) != std::string::npos)
    {
        key.erase(pos, fullWidthSpace.size());
    }

    return key;
}

bool BianHao_IsSequenceHeaderText(const std::string& text)
{
    const std::string key = BianHao_NormalizeHeaderKey(text);
    if (key.empty())
    {
        return false;
    }

    return key == "序号" ||
        key == "编号" ||
        key == "项号" ||
        key == "件号" ||
        key == "序號" ||
        key == "項號" ||
        key == "NO" ||
        key == "NO" ||
        key == "NO" ||
        key == "ITEM" ||
        key == "ITEMNO" ||
        key == "ITEMNUMBER" ||
        key.find("序号") != std::string::npos ||
        key.find("項號") != std::string::npos ||
        key.find("项号") != std::string::npos;
}

